import type { ReactNode } from "react"

type BrandingPreviewProps = {
  appName: string
  /** Shown when `appName` is empty, e.g. "OpenLMIS". */
  defaultAppName: string
  logoUrl: string
  showAppName: boolean
}

function PreviewItem({
  caption,
  children,
}: {
  caption: string
  children: ReactNode
}) {
  return (
    <figure className="flex min-w-0 flex-col gap-2">
      <figcaption className="text-xs text-muted-foreground">
        {caption}
      </figcaption>
      <div
        aria-hidden="true"
        className="flex h-32 items-center justify-center rounded-xl border bg-muted/40 p-4"
      >
        {children}
      </div>
    </figure>
  )
}

/** The branding as it lands in the browser tab, the sidebar and the sign-in page. */
export function BrandingPreview({
  appName,
  defaultAppName,
  logoUrl,
  showAppName,
}: BrandingPreviewProps) {
  const name = appName.trim() || defaultAppName

  return (
    <section
      aria-labelledby="branding-preview-title"
      className="flex flex-col gap-3"
    >
      <h2 className="text-sm font-medium" id="branding-preview-title">
        Preview
      </h2>
      <div className="grid gap-3 @xl/main:grid-cols-3">
        <PreviewItem caption="Browser Tab">
          <div className="flex max-w-full min-w-0 items-center gap-2 rounded-lg border bg-background px-3 py-1.5 text-sm shadow-xs">
            {/* oxlint-disable-next-line next/no-img-element -- items are framework-neutral, and the logo may be a local object URL */}
            <img
              alt=""
              className="size-4 shrink-0 object-contain"
              src={logoUrl}
            />
            <span className="truncate" dir="auto">
              {name}
            </span>
          </div>
        </PreviewItem>
        <PreviewItem caption="Sidebar">
          <div className="flex w-full min-w-0 items-center gap-2 rounded-lg border bg-sidebar px-3 py-2 text-sidebar-foreground shadow-xs">
            {/* oxlint-disable-next-line next/no-img-element -- items are framework-neutral, and the logo may be a local object URL */}
            <img
              alt=""
              className={
                showAppName
                  ? "h-8 max-w-24 shrink-0 object-contain"
                  : "h-6 max-w-44 object-contain"
              }
              src={logoUrl}
            />
            {showAppName && (
              <span className="truncate text-sm font-semibold" dir="auto">
                {name}
              </span>
            )}
          </div>
        </PreviewItem>
        <PreviewItem caption="Sign-In Page">
          <div className="flex min-w-0 flex-col items-center gap-1 text-center">
            {/* oxlint-disable-next-line next/no-img-element -- items are framework-neutral, and the logo may be a local object URL */}
            <img alt="" className="h-7 max-w-40 object-contain" src={logoUrl} />
            <p className="text-sm font-semibold">Sign In</p>
            <p className="line-clamp-2 text-xs text-muted-foreground">
              Enter your {name} credentials to continue.
            </p>
          </div>
        </PreviewItem>
      </div>
    </section>
  )
}

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { type ReactNode, useEffect, useState } from "react"

import { useAppForm } from "@/components/openlmis/form-fields/form"
import { SettingsList } from "@/components/openlmis/settings-list"

import { BrandingPreview } from "@/components/openlmis/system-settings-page/branding-preview"
import {
  type Branding,
  type BrandingValues,
  brandingSchema,
  LOGO_TYPES,
  logoSchema,
  MAX_APP_NAME_LENGTH,
  toBrandingValues,
} from "@/components/openlmis/system-settings-page/branding"

type BrandingFormOptions = {
  saved: Branding
  /** The page's Save button submits this form by id, and an invalid submit focuses its first error. */
  formId: string
  onSave: (values: BrandingValues) => void
}

/** The branding form, held by the page so its footer can save, cancel and see unsaved changes. */
export function useBrandingForm({
  saved,
  formId,
  onSave,
}: BrandingFormOptions) {
  return useAppForm({
    defaultValues: toBrandingValues(saved),
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: brandingSchema(saved) },
    onSubmit: ({ value }) => onSave(value),
    onSubmitInvalid: () =>
      document
        .querySelector<HTMLElement>(`#${formId} [aria-invalid="true"]`)
        ?.focus(),
  })
}

export type BrandingForm = ReturnType<typeof useBrandingForm>

/** A URL for a picked file, revoked once the file is no longer shown. */
function useObjectUrl(file: File | null) {
  const [created, setCreated] = useState<{ file: File; url: string }>()
  useEffect(() => {
    if (!file) return
    const url = URL.createObjectURL(file)
    // oxlint-disable-next-line react/set-state-in-effect -- an object URL is a browser resource, created and revoked with the file
    setCreated({ file, url })
    return () => URL.revokeObjectURL(url)
  }, [file])
  return created && created.file === file ? created.url : null
}

function useLogoUrl(
  logo: File | null | undefined,
  saved: Branding["logo"],
  defaultLogoUrl: string
) {
  // A file that fails validation keeps the saved logo on show.
  const rejected = logo instanceof File && !logoSchema.safeParse(logo).success
  const shown = logo === undefined || rejected ? saved : logo
  const file = shown instanceof File ? shown : null
  const objectUrl = useObjectUrl(file)
  if (file) return objectUrl ?? defaultLogoUrl
  return typeof shown === "string" ? shown : defaultLogoUrl
}

type BrandingSettingsProps = {
  form: BrandingForm
  saved: Branding
  formId: string
  /** The app's own name and logo, shown while nothing is set here. */
  defaultAppName: string
  defaultLogoUrl: string
  /** Locks every field while the parent saves. */
  pending?: boolean
  /** Above the fields, such as a failed save. */
  feedback?: ReactNode
}

/** App name, logo and whether the name shows beside it, with a live preview of where they appear. */
export function BrandingSettings({
  form,
  saved,
  formId,
  defaultAppName,
  defaultLogoUrl,
  pending = false,
  feedback,
}: BrandingSettingsProps) {
  const values = useStore(form.store, (state) => state.values)
  const logoUrl = useLogoUrl(values.logo, saved.logo, defaultLogoUrl)

  return (
    <div className="flex flex-col gap-6">
      {feedback}
      <form
        id={formId}
        noValidate
        onSubmit={(event) => {
          event.preventDefault()
          void form.handleSubmit()
        }}
      >
        <SettingsList>
          <form.AppField name="appName">
            {(field) => (
              <field.TextField
                description={`Up to ${MAX_APP_NAME_LENGTH} characters.`}
                disabled={pending}
                label="App Name"
                layout="row"
                maxLength={MAX_APP_NAME_LENGTH}
                placeholder={defaultAppName}
              />
            )}
          </form.AppField>
          <form.AppField name="logo" validators={{ onChange: logoSchema }}>
            {(field) => (
              <field.ImageField
                accept={LOGO_TYPES.join(",")}
                canRemove={
                  field.state.value instanceof File ||
                  (field.state.value === undefined && saved.logo !== null)
                }
                chooseLabel="Upload Logo"
                description="PNG, JPEG or WebP, up to 512 KB."
                disabled={pending}
                label="Logo"
                previewAlt="Logo"
                previewUrl={logoUrl}
                removeLabel="Remove Logo"
              />
            )}
          </form.AppField>
          <form.AppField name="showAppName">
            {(field) => (
              <field.SwitchField
                description="Turn off when the logo already shows the name."
                disabled={pending}
                label="Show Name Beside Logo"
                layout="row"
              />
            )}
          </form.AppField>
        </SettingsList>
      </form>
      <BrandingPreview
        appName={values.appName}
        defaultAppName={defaultAppName}
        logoUrl={logoUrl}
        showAppName={values.showAppName}
      />
    </div>
  )
}

import { z } from "zod"

export const LOGO_TYPES = ["image/png", "image/jpeg", "image/webp"]
export const MAX_LOGO_BYTES = 512 * 1024
export const MAX_APP_NAME_LENGTH = 20

/** The branding saved for everyone; a null name or logo means the app's own. */
export type Branding = {
  appName: string | null
  showAppName: boolean
  /** A URL, or a file picked here that the page keeps without uploading it. */
  logo: string | File | null
}

/** `logo` is a new file, null to remove the saved one, or undefined to keep it. */
export type BrandingValues = {
  appName: string
  showAppName: boolean
  logo: File | null | undefined
}

export const DEFAULT_BRANDING: Branding = {
  appName: null,
  showAppName: true,
  logo: null,
}

export const logoSchema = z
  .custom<File | null | undefined>(
    (value) => value === undefined || value === null || value instanceof File
  )
  .superRefine((file, context) => {
    if (!(file instanceof File)) return
    if (!LOGO_TYPES.includes(file.type)) {
      context.addIssue({
        code: "custom",
        message: "Choose a PNG, JPEG or WebP image.",
      })
    } else if (file.size > MAX_LOGO_BYTES) {
      context.addIssue({
        code: "custom",
        message: "Choose an image of at most 512 KB.",
      })
    }
  })

export const brandingSchema = (saved: Branding) =>
  z.object({
    appName: z
      .string()
      .trim()
      // A longer name saved before the limit stays allowed until it is changed.
      .refine(
        (name) => name.length <= MAX_APP_NAME_LENGTH || name === saved.appName,
        "Use at most 20 characters, so the name fits the sidebar."
      ),
    showAppName: z.boolean(),
    logo: logoSchema,
  })

export function toBrandingValues(saved: Branding): BrandingValues {
  return {
    appName: saved.appName ?? "",
    showAppName: saved.showAppName,
    logo: undefined,
  }
}

/** The branding once `values` are saved over `saved`. */
export function applyBranding(
  saved: Branding,
  values: BrandingValues
): Branding {
  return {
    appName: values.appName.trim() || null,
    showAppName: values.showAppName,
    logo: values.logo === undefined ? saved.logo : values.logo,
  }
}

export function isBrandingChanged(values: BrandingValues, saved: Branding) {
  const next = applyBranding(saved, values)
  return (
    next.appName !== saved.appName ||
    next.showAppName !== saved.showAppName ||
    next.logo !== saved.logo
  )
}

export const isBrandingDefault = (saved: Branding) =>
  saved.logo === null && saved.appName === null && saved.showAppName

"use client"

import { useStore } from "@tanstack/react-form"
import { InfoIcon, RotateCcwIcon, SearchXIcon } from "lucide-react"
import { type ReactNode, useRef } from "react"

import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover"
import { DataTableEmpty } from "@/components/blocks/openlmis/data-table/data-table"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { SearchInput } from "@/components/openlmis/search-input/search-input"
import { SettingsList } from "@/components/openlmis/settings-list"

import {
  buildFlagOverrides,
  type FeatureFlagDefinition,
  filterFlags,
  flagValueLabel,
  type StoredFlags,
  toFlagDraft,
} from "@/components/openlmis/system-settings-page/feature-flags"

type FeatureFlagsFormOptions = {
  flags: readonly FeatureFlagDefinition[]
  saved: StoredFlags
  /** Gets every override to store, including saved ones for flags not shown. */
  onSave: (overrides: StoredFlags) => void
}

/** The flags form, held by the page so its footer can save, cancel and see unsaved changes. */
export function useFeatureFlagsForm({
  flags,
  saved,
  onSave,
}: FeatureFlagsFormOptions) {
  return useAppForm({
    defaultValues: toFlagDraft(flags, saved),
    onSubmit: ({ value }) => onSave(buildFlagOverrides(flags, value, saved)),
  })
}

export type FeatureFlagsForm = ReturnType<typeof useFeatureFlagsForm>

function FlagAbout({ flag }: { flag: FeatureFlagDefinition }) {
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            aria-label={`About ${flag.label}`}
            size="icon-xs"
            type="button"
            variant="ghost"
          />
        }
      >
        <InfoIcon />
      </PopoverTrigger>
      <PopoverContent align="start">
        <PopoverHeader>
          <PopoverTitle>{flag.label}</PopoverTitle>
          <PopoverDescription>{flag.description}</PopoverDescription>
        </PopoverHeader>
        <p className="text-sm">Used by: {flag.usedBy}.</p>
      </PopoverContent>
    </Popover>
  )
}

type FeatureFlagsSettingsProps = {
  form: FeatureFlagsForm
  flags: readonly FeatureFlagDefinition[]
  /** The page's Save button submits this form by id. */
  formId: string
  search: string
  onSearchChange: (search: string) => void
  /** Locks every flag while the parent saves. */
  pending?: boolean
  /** Between the search and the flags, such as a failed save. */
  feedback?: ReactNode
}

/** Each flag as a row: a switch or a select, what it inherits, and a Reset once it is changed here. */
export function FeatureFlagsSettings({
  form,
  flags,
  formId,
  search,
  onSearchChange,
  pending = false,
  feedback,
}: FeatureFlagsSettingsProps) {
  const values = useStore(form.store, (state) => state.values)
  const searchBox = useRef<HTMLDivElement>(null)
  const visible = filterFlags(flags, search)

  const clearSearch = () => {
    onSearchChange("")
    searchBox.current?.querySelector("input")?.focus()
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="w-full @2xl/main:w-72" ref={searchBox}>
        <SearchInput
          label="Search Feature Flags"
          onValueChange={onSearchChange}
          placeholder="Search By Name, Key Or Screen"
          value={search}
        />
      </div>
      {feedback}
      <form
        id={formId}
        noValidate
        onSubmit={(event) => {
          event.preventDefault()
          void form.handleSubmit()
        }}
      >
        {visible.length === 0 ? (
          <DataTableEmpty
            action={
              <Button
                onClick={clearSearch}
                size="sm"
                type="button"
                variant="outline"
              >
                Clear Filters
              </Button>
            }
            description="Try another name, key or screen."
            icon={<SearchXIcon />}
            title="No Feature Flags Match"
          />
        ) : (
          <SettingsList>
            {visible.map((flag) => {
              const { inherited } = flag
              const changed = values[flag.key]?.overridden ?? false
              return (
                <form.AppField
                  key={flag.key}
                  listeners={{
                    onChange: ({ value }) =>
                      form.setFieldValue(
                        `${flag.key}.overridden`,
                        value !== inherited.value
                      ),
                  }}
                  name={`${flag.key}.value`}
                >
                  {(field) => {
                    const shared = {
                      action: (
                        <>
                          <FlagAbout flag={flag} />
                          {changed && (
                            <Button
                              aria-label={`Reset ${flag.label}`}
                              disabled={pending}
                              onClick={(event) => {
                                const row = event.currentTarget.closest(
                                  "[data-slot='field']"
                                )
                                field.handleChange(inherited.value)
                                // The button goes away, so focus moves to the control it reset.
                                row
                                  ?.querySelector<HTMLElement>(
                                    "[role='switch'], [data-slot='select-trigger']"
                                  )
                                  ?.focus()
                              }}
                              size="xs"
                              type="button"
                              variant="destructive"
                            >
                              <RotateCcwIcon data-icon="inline-start" />
                              Reset
                            </Button>
                          )}
                        </>
                      ),
                      description: (
                        <>
                          <code className="font-mono text-xs" dir="ltr">
                            {flag.key}
                          </code>
                          {!changed &&
                            inherited.source === "deployment" &&
                            " · Set by the deployment"}
                          {changed && (
                            <span className="block text-primary">
                              Changed here ·{" "}
                              {inherited.source === "deployment"
                                ? "The deployment sets "
                                : "The default is "}
                              <span className="font-semibold">
                                {flagValueLabel(flag, inherited.value)}
                              </span>
                            </span>
                          )}
                        </>
                      ),
                      disabled: pending,
                      label: flag.label,
                      layout: "row" as const,
                    }
                    return (
                      <div className="relative">
                        {changed && (
                          <span
                            aria-hidden="true"
                            className="absolute inset-y-3 start-0 w-0.5 rounded-full bg-primary"
                          />
                        )}
                        {flag.type === "boolean" ? (
                          <field.SwitchField {...shared} />
                        ) : (
                          <field.SelectField {...shared} items={flag.options} />
                        )}
                      </div>
                    )
                  }}
                </form.AppField>
              )
            })}
          </SettingsList>
        )}
      </form>
    </div>
  )
}

export type FlagValue = boolean | string

/** Where a flag's value comes from when nothing is set here. */
export type InheritedFlag = {
  value: FlagValue
  source: "default" | "deployment"
}

type FlagText = {
  key: string
  label: string
  description: string
  /** The screens it changes, e.g. "Requisitions > Approve". */
  usedBy: string
  inherited: InheritedFlag
}

export type FeatureFlagDefinition =
  | (FlagText & { type: "boolean" })
  | (FlagText & {
      type: "enum"
      options: readonly { value: string; label: string }[]
    })

/** The overrides saved for everyone; a flag missing from it inherits. */
export type StoredFlags = Record<string, FlagValue>

type FlagEntry = { value: FlagValue; overridden: boolean }

/** Every flag's value in the form, and whether it overrides what it inherits. */
export type FlagDraft = Record<string, FlagEntry>

export function flagValueLabel(flag: FeatureFlagDefinition, value: FlagValue) {
  if (flag.type === "boolean") return value ? "On" : "Off"
  return flag.options.find((option) => option.value === value)?.label ?? ""
}

export function toFlagDraft(
  flags: readonly FeatureFlagDefinition[],
  saved: StoredFlags
): FlagDraft {
  return Object.fromEntries(
    flags.map((flag) => {
      const stored = saved[flag.key]
      return [
        flag.key,
        stored === undefined
          ? { value: flag.inherited.value, overridden: false }
          : { value: stored, overridden: true },
      ]
    })
  )
}

/** Overrides for the flags shown, keeping any saved for flags this screen does not know. */
export function buildFlagOverrides(
  flags: readonly FeatureFlagDefinition[],
  draft: FlagDraft,
  saved: StoredFlags
): StoredFlags {
  const known = new Set(flags.map((flag) => flag.key))
  const unknown = Object.entries(saved).filter(([key]) => !known.has(key))
  const overridden = flags
    .filter((flag) => draft[flag.key]?.overridden)
    .map((flag) => [flag.key, draft[flag.key]?.value ?? flag.inherited.value])
  return Object.fromEntries([...unknown, ...overridden])
}

export function isFlagsChanged(
  flags: readonly FeatureFlagDefinition[],
  draft: FlagDraft,
  saved: StoredFlags
) {
  const current = toFlagDraft(flags, saved)
  return flags.some(
    ({ key }) =>
      draft[key]?.value !== current[key]?.value ||
      draft[key]?.overridden !== current[key]?.overridden
  )
}

/** Flags whose key, name, description or screens contain `search`. */
export function filterFlags(
  flags: readonly FeatureFlagDefinition[],
  search: string
) {
  const needle = search.trim().toLowerCase()
  if (!needle) return flags
  return flags.filter((flag) =>
    [flag.key, flag.label, flag.description, flag.usedBy].some((text) =>
      text.toLowerCase().includes(needle)
    )
  )
}

